#!/bin/zsh -f
# run as the person: no agent markers, scratch XDG, scratch loom first on the person's PATH (or $PPATH if set)
exec env -i HOME=$HOME USER=$USER LOGNAME=$USER LANG=en_US.UTF-8 TERM=xterm-256color TMPDIR=$TMPDIR \
  XDG_CONFIG_HOME=${SCRATCH:?}/study/live/xdg/config XDG_DATA_HOME=${SCRATCH:?}/study/live/xdg/data XDG_CACHE_HOME=${SCRATCH:?}/study/live/xdg/cache \
  PATH="${PPATH:-${SCRATCH:?}/study/live/uv/bin:$HOME/miniconda3/bin:$HOME/miniconda3/condabin:$HOME/.deno/bin:/opt/homebrew/bin:$HOME/.opam/default/bin:/Library/Frameworks/Python.framework/Versions/3.11/bin:/usr/local/bin:/System/Cryptexes/App/usr/bin:/usr/bin:/bin:/usr/sbin:/sbin:/var/run/com.apple.security.cryptexd/codex.system/bootstrap/usr/local/bin:/var/run/com.apple.security.cryptexd/codex.system/bootstrap/usr/bin:/var/run/com.apple.security.cryptexd/codex.system/bootstrap/usr/appleinternal/bin:/pkg/env/global/bin:/Library/Apple/usr/bin:/Library/TeX/texbin:/Applications/VMware Fusion.app/Contents/Public:$HOME/.local/bin:$HOME/.cargo/bin:/opt/homebrew/bin:/Library/Frameworks/Python.framekwork/Versions/3.11/bin:/opt/homebrew/opt/python@3.11/libexec/bin:$HOME/.config/emacs/bin:/usr/local/texlive/2024/bin/universal-darwin}" "$@"
